    // Section 1
    privacy_sec_1_title: { en: 'General Information', de: 'Allgemeine Informationen', et: 'Üldteave', fr: 'Informations générales', it: 'Informazioni generali' },
    privacy_sec_1_content: {
        en: 'We take the protection of your personal data very seriously. Adraca processes personal data in accordance with applicable statutory data protection regulations of India and aligns its practices with the principles and requirements of the GDPR of the European Union.',
        de: 'Wir nehmen den Schutz Ihrer persönlichen Daten sehr ernst. Adraca verarbeitet personenbezogene Daten gemäß den geltenden gesetzlichen Datenschutzbestimmungen Indiens und richtet seine Praktiken an den Grundsätzen und Anforderungen der DSGVO der Europäischen Union aus.',
        et: 'Võtame teie isikuandmete kaitset väga tõsiselt. Adraca töötleb isikuandmeid vastavalt India kehtivatele seadusjärgsetele andmekaitse-eeskirjadele ja joondab oma tegevuse Euroopa Liidu GDPR-i põhimõtete ja nõuetega.',
        fr: 'Nous prenons très au sérieux la protection de vos données personnelles. Adraca traite les données personnelles conformément aux réglementations légales applicables en matière de protection des données en Inde et aligne ses pratiques sur les principes et exigences du RGPD de l\'Union européenne.',
        it: 'Prendiamo molto sul serio la protezione dei tuoi dati personali. Adraca tratta i dati personali in conformità con le normative vigenti in materia di protezione dei dati dell\'India e allinea le sue pratiche ai principi e ai requisiti del GDPR dell\'Unione Europea.',
    },
