    // Section 6
    privacy_sec_6_title: { en: 'Data Sharing and Processors', de: 'Datenfreigabe und Auftragsverarbeiter', et: 'Andmete jagamine ja volitatud töötlejad', fr: 'Partage de données et sous-traitants', it: 'Condivisione dei dati e responsabili' },
    privacy_sec_6_content: {
        en: 'We do not sell personal data. We may share data with trusted third-party service providers (processors) under appropriate DPAs and GDPR safeguards.',
        de: 'Wir verkaufen keine personenbezogenen Daten. Wir können Daten unter geeigneten Auftragsverarbeitungsverträgen (AVV) und DSGVO-Schutzmaßnahmen an vertrauenswürdige Drittanbieter (Auftragsverarbeiter) weitergeben.',
        et: 'Me ei müü isikuandmeid. Võime jagada andmeid usaldusväärsete kolmandast osapoolest teenusepakkujatega (volitatud töötlejatega) vastavate andmetöötluslepingute ja GDPR-i kaitsemeetmete alusel.',
        fr: 'Nous ne vendons pas de données personnelles. Nous pouvons partager des données avec des prestataires de services tiers de confiance (sous-traitants) dans le cadre de DPA appropriés et de garanties RGPD.',
        it: 'Non vendiamo dati personali. Potremmo condividere i dati con fornitori di servizi terzi fidati (responsabili del trattamento) in base ad adeguati DPA e garanzie GDPR.',
    },
    // Section 7
    privacy_sec_7_title: { en: 'International Data Transfers', de: 'Internationale Datentransfers', et: 'Rahvusvahelised andmete edastused', fr: 'Transferts internationaux de données', it: 'Trasferimenti internazionali di dati' },
    privacy_sec_7_content: {
        en: 'Adraca operates a Global R&D Hub located in India. Data transfers outside the EU/EEA are protected by ISO/IEC 27001 measures and standard contractual clauses.',
        de: 'Adraca betreibt ein globales F&E-Zentrum in Indien. Datentransfers außerhalb der EU/EWR sind durch ISO/IEC 27001-Maßnahmen und Standardvertragsklauseln geschützt.',
        et: 'Adraca opereerib globaalset TA-keskust Indias. Andmete edastamine väljapoole EL-i/EMP-d on kaitstud ISO/IEC 27001 meetmete ja standardsete lepinguklauslitega.',
        fr: 'Adraca exploite un hub R&D mondial situé en Inde. Les transferts de données en dehors de l\'UE/EEE sont protégés par des mesures ISO/IEC 27001 et des clauses contractuelles types.',
        it: 'Adraca gestisce un hub globale di ricerca e sviluppo situato in India. I trasferimenti di dati al di fuori dell\'UE/SEE sono protetti da misure ISO/IEC 27001 e clausole contrattuali standard.',
    },
