        en: 'Instantly categorize enterprise AI systems into EU AI Act risk levels (High-Risk, Limited, or Minimal) using our proprietary Art. 6 logic engine.',
        de: 'Kategorisieren Sie Unternehmens-KI-Systeme sofort in EU-KI-Gesetz-Risikostufen (Hochrisiko, Begrenzt oder Minimal) mit unserer proprietären Art. 6 Logik-Engine.',
        et: 'Liigitage ettevõtte AI-süsteemid koheselt EL-i AI-määruse riskitasemetesse (kõrge riskiga, piiratud või minimaalne), kasutades meie omanduslikku art. 6 loogikamootorit.',
        fr: 'Catégorisez instantanément les systèmes d\'IA d\'entreprise en niveaux de risque de la loi européenne sur l\'IA (haut risque, limité ou minimal) à l\'aide de notre moteur logique exclusif Art. 6.',
        it: 'Classifica istantaneamente i sistemi di IA aziendali nei livelli di rischio della legge UE sull\'IA (alto rischio, limitato o minimo) utilizzando il nostro motore logico proprietario Art. 6.',
