    real_ownership_desc: { en: 'Interns don\'t fix bugs here. You\'ll own a feature from concept to deployment.', de: 'Praktikanten beheben hier keine Bugs. Du verantwortest ein Feature von Konzept bis Deployment.', et: 'Praktikandid ei paranda siin vigu. Sa vastutad funktsiooni eest kontseptsioonist juurutamiseni.', fr: 'Les stagiaires ne corrigent pas de bugs ici. Vous posséderez une fonctionnalité du concept au déploiement.', it: 'Gli stagisti non correggono bug qui. Possiederai una funzionalità dal concetto al rilascio.' },
