        de: 'Eine gehärtete, Air-Gapped-Betriebsumgebung, die auf Arch Linux und Trusted Execution Environments (TEEs) aufgebaut ist. Wir verlassen uns nicht auf US-basierte Hyperscaler. Wir bauen Bare-Metal-Souveränität.',
