    // Onboarding Engine Page
    connection_established: { en: 'Connection Established', de: 'Verbindung hergestellt', et: 'Ühendus loodud', fr: 'Connexion Établie', it: 'Connessione Stabilita' },
    legacy_to: { en: 'Automated', de: 'Automatisiert', et: 'Automatiseeritud', fr: 'Automatisé', it: 'Automatizzato' },
    limitless: { en: 'Ingestion Engine.', de: 'Ingestions-Engine.', et: 'Sissevõtumootor.', fr: 'Moteur d\'Ingestion.', it: 'Motore di Ingestione.' },
    migration_hero_desc: { en: 'The Adraca Onboarding Engine. A self-hosted binary that ingests petabytes of legacy data, sanitizes it, and structures it for the Sovereign Validator.', de: 'Die Adraca Onboarding Engine. Eine selbst gehostete Binärdatei, die Petabytes an Legacy-Daten aufnimmt, bereinigt und für den Sovereign Validator strukturiert.', et: 'Adraca Sisseelamise Mootor. Isemajandav binaarfail, mis võtab vastu petabaite pärandandmeid, puhastab need ja struktureerib Suveräänse Validaatori jaoks.', fr: 'Le moteur d\'intégration Adraca. Un binaire auto-hébergé qui ingère des pétaoctets de données héritées, les assainit et les structure pour le validateur souverain.', it: 'Il motore di onboarding Adraca. Un binario self-hosted che ingerisce petabyte di dati legacy, li sanifica e li struttura per il Sovereign Validator.' },
    initiate_pipeline: { en: 'Start Ingestion', de: 'Ingestion starten', et: 'Alusta sissevõttu', fr: 'Démarrer l\'Ingestion', it: 'Avvia Ingestione' },
    speed_40gbs: { en: '> THROUGHPUT: 40GB/s', de: '> DURCHSATZ: 40GB/s', et: '> LÄBILASKVUS: 40GB/s', fr: '> DÉBIT: 40GB/s', it: '> THROUGHPUT: 40GB/s' },
    migration_engine: { en: 'Onboarding Engine', de: 'Onboarding Engine', et: 'Sisseelamise Mootor', fr: 'Moteur d\'Intégration', it: 'Motore di Onboarding' },
    migration_engine_desc: { en: 'Automated format transpilers for effortless data sovereignty.', de: 'Automatisierte Format-Transpiler für mühelose Datensouveränität.', et: 'Automatiseeritud formaadi transpilaatorid pingutusteta andmesuveräänsuse tagamiseks.', fr: 'Transpilateurs de format automatisés pour une souveraineté des données sans effort.', it: 'Transpilatori di formato automatizzati per la sovranità dei dati senza sforzo.' },

    express_transfer: { en: 'Sanitization Pipeline', de: 'Bereinigungspipeline', et: 'Puhastustorustik', fr: 'Pipeline d\'Assainissement', it: 'Pipeline di Sanificazione' },
    express_transfer_desc: { en: 'Automated PII redaction and schema normalization happening entirely within your VPC before data touches the index.', de: 'Automatisierte PII-Redaktion und Schema-Normalisierung, die vollständig in Ihrer VPC stattfindet, bevor Daten den Index berühren.', et: 'Automatiseeritud PII redigeerimine ja skeemi normaliseerimine, mis toimub täielikult teie VPC-s enne andmete indeksisse jõudmist.', fr: 'Rédaction PII automatisée et normalisation de schéma se produisant entièrement au sein de votre VPC avant que les données ne touchent l\'index.', it: 'Redazione PII automatizzata e normalizzazione dello schema che avvengono interamente all\'interno del tuo VPC prima che i dati tocchino l\'indice.' },
    // Deployment Architecture Section
    deploy_arch_title: { en: 'Zero-Trust by Design.', de: 'Zero-Trust by Design.', et: 'Null-usaldus disain.', fr: 'Zero-Trust by Design.', it: 'Zero-Trust by Design.' },
    deploy_arch_body: {
        en: "Most AI platforms simply wrap an API call to a US provider. Adraca deploys a 'Sovereign Validator' node inside your infrastructure.",
        de: "Die meisten KI-Plattformen verpacken einfach einen API-Aufruf an einen US-Anbieter. Adraca stellt einen 'Sovereign Validator'-Knoten in Ihrer Infrastruktur bereit.",
        et: "Enamik tehisintellekti platvorme lihtsalt pakib API kõne USA teenusepakkujale. Adraca paigaldab 'Sovereign Validator' sõlme teie infrastruktuuri sisse.",
        fr: "La plupart des plateformes d'IA enveloppent simplement un appel API vers un fournisseur américain. Adraca déploie un nœud 'Sovereign Validator' au sein de votre infrastructure.",
        it: "La maggior parte delle piattaforme AI avvolge semplicemente una chiamata API a un provider statunitense. Adraca distribuisce un nodo 'Sovereign Validator' all'interno della tua infrastruttura.",
    },

    deploy_arch_list_1: { en: 'Data never leaves your VPC.', de: 'Daten verlassen niemals Ihre VPC.', et: 'Andmed ei lahku kunagi teie VPC-st.', fr: 'Les données ne quittent jamais votre VPC.', it: 'I dati non lasciano mai il tuo VPC.' },
    deploy_arch_list_2: { en: 'Models run on local hardware.', de: 'Modelle laufen auf lokaler Hardware.', et: 'Mudelid töötavad kohalikul riistvaral.', fr: 'Les modèles s\'exécutent sur du matériel local.', it: 'I modelli girano su hardware locale.' },
    deploy_arch_list_3: { en: 'Audit logs are cryptographically signed.', de: 'Audit-Protokolle sind kryptografisch signiert.', et: 'Auditilogid on krüptograafiliselt allkirjastatud.', fr: 'Les journaux d\'audit sont signés cryptographiquement.', it: 'I log di audit sono firmati crittograficamente.' },

    term_log_1: { en: '> SYSTEM_CHECK_INITIATED...', de: '> SYSTEM_CHECK_INITIATED...', et: '> SYSTEM_CHECK_INITIATED...', fr: '> SYSTEM_CHECK_INITIATED...', it: '> SYSTEM_CHECK_INITIATED...' },
    term_log_2: { en: '> DETECTING_CLOUD_PROVIDER... [AWS_EU_WEST_3]', de: '> DETECTING_CLOUD_PROVIDER... [AWS_EU_WEST_3]', et: '> DETECTING_CLOUD_PROVIDER... [AWS_EU_WEST_3]', fr: '> DETECTING_CLOUD_PROVIDER... [AWS_EU_WEST_3]', it: '> DETECTING_CLOUD_PROVIDER... [AWS_EU_WEST_3]' },
