    term_log_4: { en: '> VERIFYING_TPM_SIGNATURE... [MATCH]', de: '> VERIFYING_TPM_SIGNATURE... [MATCH]', et: '> VERIFYING_TPM_SIGNATURE... [MATCH]', fr: '> VERIFYING_TPM_SIGNATURE... [MATCH]', it: '> VERIFYING_TPM_SIGNATURE... [MATCH]' },
    term_log_5: { en: '> EXT_CONNECTION_TO_OPENAI... [BLOCKED_BY_FIREWALL]', de: '> EXT_CONNECTION_TO_OPENAI... [BLOCKED_BY_FIREWALL]', et: '> EXT_CONNECTION_TO_OPENAI... [BLOCKED_BY_FIREWALL]', fr: '> EXT_CONNECTION_TO_OPENAI... [BLOCKED_BY_FIREWALL]', it: '> EXT_CONNECTION_TO_OPENAI... [BLOCKED_BY_FIREWALL]' },
    term_log_6: { en: '> LOCAL_INFERENCE_ENGINE... [ONLINE]', de: '> LOCAL_INFERENCE_ENGINE... [ONLINE]', et: '> LOCAL_INFERENCE_ENGINE... [ONLINE]', fr: '> LOCAL_INFERENCE_ENGINE... [ONLINE]', it: '> LOCAL_INFERENCE_ENGINE... [ONLINE]' },
    schema_map: { en: 'Format Transpiler', de: 'Format-Transpiler', et: 'Formaadi Transpilaator', fr: 'Transpilateur de Format', it: 'Transpilatore di Formato' },
    schema_map_desc: { en: 'Zero-code translation of SQL/Oracle dumps into graph-native structures compliant with Adraca standards.', de: 'Zero-Code-Übersetzung von SQL/Oracle-Dumps in graphnative Strukturen, die den Adraca-Standards entsprechen.', et: 'Nullkoodiga SQL/Oracle tõmmiste tõlkimine graafikutepõhistesse struktuuridesse, mis vastavad Adraca standarditele.', fr: 'Traduction sans code des dumps SQL/Oracle vers des structures natives de graphe conformes aux normes Adraca.', it: 'Traduzione zero-code dei dump SQL/Oracle in strutture native a grafo conformi agli standard Adraca.' },
    conversion_auto: { en: 'CONVERSION: AUTO_DETECT', de: 'KONVERSION: AUTO_ERKENNUNG', et: 'TEISENDUS: AUTOMAATNE_TUVASTUS', fr: 'CONVERSION: DÉTECTION_AUTO', it: 'CONVERSIONE: AUTO_RILEVAMENTO' },

    live_validation: { en: 'Ingest Integrity', de: 'Ingestion-Integrität', et: 'Sissevõtu Terviklikkus', fr: 'Intégrité d\'Ingestion', it: 'Integrità dell\'Ingestione' },
    live_validation_desc: { en: 'Bit-level verification of every ingested block against the source hash. We prove mathematically that 100% of the data made it across.', de: 'Bit-Level-Verifizierung jedes aufgenommenen Blocks gegen den Quell-Hash. Wir beweisen mathematisch, dass 100% der Daten übertragen wurden.', et: 'Iga vastuvõetud ploki bititaseme kontroll algallika räsi vastu. Tõestame matemaatiliselt, et 100% andmetest jõudis kohale.', fr: 'Vérification au niveau du bit de chaque bloc ingéré par rapport au hachage source. Nous prouvons mathématiquement que 100 % des données ont été transférées.', it: 'Verifica a livello di bit di ogni blocco ingerito rispetto all\'hash di origine. Dimostriamo matematicamente che il 100% dei dati è stato trasferito.' },
    integrity_100: { en: 'INTEGRITY: 100%', de: 'INTEGRITÄT: 100%', et: 'TERVIKLIKKUS: 100%', fr: 'INTÉGRITÉ: 100%', it: 'INTEGRITÀ: 100%' },

    current_batch: { en: 'Current Batch', de: 'Aktueller Batch', et: 'Praegune partii', fr: 'Lot Actuel', it: 'Lotto Corrente' },
    speed_label: { en: 'Speed', de: 'Geschw.', et: 'Kiirus', fr: 'Vitesse', it: 'Velocità' },
    cutover_confidence: { en: 'Cutover Confidence', de: 'Umschalt-Sicherheit', et: 'Ülemineku kindlus', fr: 'Confiance de Basculement', it: 'Confidenza di Cutover' },
    cutover_desc: { en: 'Visualizing the validation cycle. We run dual-write phases with live integrity checks to ensure zero data loss before the Sovereign Validator begins its audit.', de: 'Visualisierung des Umschaltprozesses. Wir führen Dual-Write-Phasen durch, um null Datenverlust während des endgültigen Wechsels sicherzustellen.', et: 'Üleminekuprotsessi visualiseerimine. Käitame topeltkirjutamise faase, et tagada null andmekadu lõpliku vahetuse ajal.', fr: 'Visualisation du processus de basculement. Nous exécutons des phases de double écriture pour garantir aucune perte de données lors du changement final.', it: 'Visualizzazione del processo di cutover. Eseguiamo fasi di dual-write per garantire zero perdita di dati durante lo switch finale.' },
    phase_1: { en: 'PHASE 1: SNAPSHOT UPLOAD', de: 'PHASE 1: SNAPSHOT-UPLOAD', et: 'FAAS 1: SNAPSHOTI ÜLESLAADIMINE', fr: 'PHASE 1: TÉLÉCHARGEMENT D\'INSTANTANÉ', it: 'FASE 1: UPLOAD SNAPSHOT' },
    phase_2: { en: 'PHASE 2: DELTA SYNC', de: 'PHASE 2: DELTA-SYNC', et: 'FAAS 2: DELTA SÜNKROONIMINE', fr: 'PHASE 2: SYNCHRONISATION DELTA', it: 'FASE 2: SINCRONIZZAZIONE DELTA' },
    phase_3: { en: 'PHASE 3: COMPLIANCE CERTIFICATION', de: 'PHASE 3: VALIDIERUNG', et: 'FAAS 3: VALIDEERIMINE', fr: 'PHASE 3: VALIDATION', it: 'FASE 3: CONVALIDA' },
