    // Security Sovereignty Page
    perimeter_secure: { en: 'Perimeter Secure', de: 'Perimeter Sicher', et: 'Perimeeter turvaline', fr: 'Périmètre Sécurisé', it: 'Perimetro Sicuro' },
    data_sovereignty_hero: { en: 'Localized Governance &', de: 'Daten', et: 'Andmete', fr: 'Données', it: 'Dati' },
    sovereignty_hero: { en: 'Sovereignty.', de: 'Souveränität.', et: 'Suveräänsus.', fr: 'Souveraineté.', it: 'Sovranità.' },
    security_hero_desc_start: { en: 'Confidential Computing at Scale. We utilize Trusted Execution Environments (TEEs) to ensure code and data remain encrypted even while in use by the processor.', de: 'Vertrauliches Computing im großen Maßstab. Wir verwenden Trusted Execution Environments (TEEs), um sicherzustellen, dass Code und Daten auch während der Verarbeitung durch den Prozessor verschlüsselt bleiben.', et: 'Konfidentsiaalne arvutus suures mahus. Kasutame usaldusväärseid täitmiskeskkondi (TEE), et tagada koodi ja andmete krüpteeritus isegi protsessori kasutamise ajal.', fr: 'Informatique confidentielle à grande échelle. Nous utilisons des environnements d\'exécution fiables (TEE) pour garantir que le code et les données restent chiffrés même lorsqu\'ils sont utilisés par le processeur.', it: 'Confidential Computing su larga scala. Utilizziamo Trusted Execution Environments (TEE) per garantire che codice e dati rimangano crittografati anche durante l\'uso da parte del processore.' },
    your_jurisdiction: { en: 'in TEE Enclaves', de: 'in TEE-Enklaven', et: 'TEE enkalavides', fr: 'dans les enclaves TEE', it: 'in enclavi TEE' },
    security_hero_desc_end: { en: '.', de: 'verlassen.', et: '.', Fr: '.', it: '.' },
    authorize_access: { en: 'Authorize Access', de: 'Zugriff autorisieren', et: 'Autoriseeri juurdepääs', fr: 'Autoriser l\'Accès', it: 'Autorizza Accesso' },
    encryption_aes: { en: 'ENCRYPTION: AES-256-GCM', de: 'VERSCHLÜSSELUNG: AES-256-GCM', et: 'KRÜPTEERIMINE: AES-256-GCM', fr: 'CHIFFREMENT: AES-256-GCM', it: 'CRITTOGRAFIA: AES-256-GCM' },
    defense_protocols: { en: 'Defense Protocols', de: 'Verteidigungsprotokolle', et: 'Kaitseprotokollid', fr: 'Protocoles de Défense', it: 'Protocolli di Difesa' },
    hover_to_scan: { en: 'Hover to scan for details.', de: 'Zum Scannen hoveren.', et: 'Hõlju skannimiseks.', fr: 'Survolez pour scanner les détails.', it: 'Passa il mouse per scansionare i dettagli.' },

    sovereign_cloud: { en: 'TEE Enclaves', de: 'TEE-Enklaven', et: 'TEE Enklaavid', fr: 'Enclaves TEE', it: 'Enclavi TEE' },
    sovereign_cloud_desc: { en: 'Intel SGX / AMD SEV protected memory regions where sensitive validation logic executes in total isolation from the host OS. Even root users cannot inspect the memory.', de: 'Intel SGX / AMD SEV geschützte Speicherbereiche. Selbst Root-Benutzer können den Speicher nicht einsehen.', et: 'Intel SGX / AMD SEV kaitstud mälupiirkonnad. Isegi juurkasutajad ei saa mälu kontrollida.', fr: 'Régions de mémoire protégées Intel SGX / AMD SEV. Même les utilisateurs root ne peuvent pas inspecter la mémoire.', it: 'Regioni di memoria protette Intel SGX / AMD SEV. Nemmeno gli utenti root possono ispezionare la memoria.' },
    geo_lock_active: { en: '> ENCLAVE: SECURE', de: '> ENKLAVE: SICHER', et: '> ENKLAAV: TURVALINE', fr: '> ENCLAVE: SÉCURISÉE', it: '> ENCLAVE: SICURA' },
    cross_border_denied: { en: '> HOST_OS: BLOCKED', de: '> HOST_OS: BLOCKIERT', et: '> HOST_OS: BLOKEERITUD', fr: '> HOST_OS: BLOQUÉ', it: '> HOST_OS: BLOCCATO' },
    audit_log_immutable: { en: '> MEMORY_ENCRYPTION: ON', de: '> SPEICHERVERSCHLÜSSELUNG: EIN', et: '> MÄLU_KRÜPTEERIMINE: SEES', fr: '> CHIFFREMENT_MÉMOIRE: MARCHE', it: '> CRITTOGRAFIA_MEMORIA: ON' },

    private_ai: { en: 'Confidential Computing', de: 'Confidential Computing', et: 'Konfidentsiaalne Arvutus', fr: 'Informatique Confidentielle', it: 'Confidential Computing' },
    private_ai_desc: { en: 'Data is never exposed to the hypervisor or cloud provider. Full memory encryption guarantees zero-trust execution even on compromised public clouds.', de: 'Daten sind niemals dem Hypervisor oder Cloud-Anbieter ausgesetzt. Vollständige Speicherverschlüsselung garantiert Zero-Trust-Ausführung.', et: 'Andmed ei ole kunagi hüperviisorile ega pilveteenuse pakkujale nähtavad. Täielik mälu krüpteerimine tagab null-usalduse täitmise.', fr: 'Les données ne sont jamais exposées à l\'hyperviseur ou au fournisseur de cloud. Le chiffrement complet de la mémoire garantit une exécution sans confiance.', it: 'I dati non vengono mai esposti all\'hypervisor o al provider cloud. La crittografia completa della memoria garantisce l\'esecuzione zero-trust.' },
    zero_knowledge_true: { en: '> HYPERVISOR: BLIND', de: '> HYPERVISOR: BLIND', et: '> HÜPERVIISOR: PIME', fr: '> HYPERVISEUR: AVEUGLE', it: '> HYPERVISOR: CIECO' },
    raw_data_unseen: { en: '> MEMORY_DUMP: DENIED', de: '> SPEICHERAUSZUG: VERWEIGERT', et: '> MÄLU_TÕMMIS: KEELATUD', fr: '> DUMP_MÉMOIRE: REFUSÉ', it: '> DUMP_MEMORIA: NEGATO' },
    model_weights_secure: { en: '> EXECUTION: ISOLATED', de: '> AUSFÜHRUNG: ISOLIERT', et: '> TÄITMINE: ISOLEERITUD', fr: '> EXÉCUTION: ISOLÉE', it: '> ESECUZIONE: ISOLATA' },

    threat_sentinel: { en: 'Regulatory Guardrails', de: 'Bedrohungswächter', et: 'Ohuvalvur', fr: 'Sentinelle de Menace', it: 'Sentinella delle Minacce' },
    threat_sentinel_desc: { en: 'Real-time adversarial defense system that detects and neutralizes model drift and non-compliant outputs before they breach regulatory thresholds.', de: 'Echtzeit-Abwehrsystem, das Modellvergiftungs- und Extraktionsangriffe erkennt und neutralisiert.', et: 'Reaalajas vastase kaitse süsteem, mis tuvastab ja neutraliseerib mudeli mürgitamise ja eraldamise rünnakud.', fr: 'Système de défense contradictoire en temps réel qui détecte et neutralise les attaques d\'empoisonnement et d\'extraction de modèles.', it: 'Sistema di difesa avversaria in tempo reale che rileva e neutralizza gli attacchi di avvelenamento ed estrazione del modello.' },
    anomaly_detect_99: { en: '> ANOMALY_DETECT: 99.9%', de: '> ANOMALIE_ERKENNUNG: 99.9%', et: '> ANOMAALIA_TUVASTUS: 99.9%', fr: '> DÉTECTION_ANOMALIE: 99.9%', it: '> ANOMALY_DETECT: 99.9%' },
    poison_filter_on: { en: '> POISON_FILTER: ON', de: '> GIFT_FILTER: EIN', et: '> MÜRGI_FILTER: SEES', fr: '> FILTRE_POISON: MARCHE', it: '> POISON_FILTER: ON' },
    response_automated: { en: '> RESPONSE: AUTOMATED', de: '> REAKTION: AUTOMATISIERT', et: '> VASTUS: AUTOMATISEERITUD', fr: '> RÉPONSE: AUTOMATISÉE', it: '> RISPOSTA: AUTOMATIZZATA' },

    global_watchtower: { en: 'Global Watchtower', de: 'Globaler Wachturm', et: 'Globaalne vaatetorn', fr: 'Tour de Guet Globale', it: 'Torre di Guardia Globale' },
    watchtower_desc: { en: 'Monitoring the integrity of distributed Sovereign Validator nodes worldwide. Live status reporting ensuring continuous compliance for multi-region enterprise AI deployments.', de: 'Überwachung der Integrität souveräner Datenknoten weltweit. Live-Statusberichte gewährleisten Compliance und Sicherheit.', et: 'Suveräänsete andmesõlmede terviklikkuse jälgimine kogu maailmas. Reaalajas olekuaruandlus tagab vastavuse ja ohutuse.', fr: 'Surveillance de l\'intégrité des nœuds de données souverains dans le monde entier. Les rapports d\'état en direct garantissent la conformité et la sécurité.', it: 'Monitoraggio dell\'integrità dei nodi dati sovrani in tutto il mondo. Il report live garantisce conformità e sicurezza.' },
