    node_tokyo: { en: 'NODE_TOKYO', de: 'KNOTEN_TOKIO', et: 'SÕLM_TOKYO', fr: 'NŒUD_TOKYO', it: 'NODO_TOKYO' },
    secure_integrity: { en: 'STATUS: COMPLIANT | INTEGRITY: 100%', de: 'SICHER [INTEGRITÄT 100%]', et: 'TURVALINE [TERVIKLIKKUS 100%]', fr: 'SÉCURISÉ [INTÉGRITÉ 100%]', it: 'SICURO [INTEGRITÀ 100%]' },
    intrusion_attempt: { en: 'INTRUSION_ATTEMPT_IP_88.2', de: 'EINDRINGVERSUCH_IP_88.2', et: 'SISSETUNGI_KATSE_IP_88.2', fr: 'TENTATIVE_INTRUSION_IP_88.2', it: 'TENTATIVO_INTRUSIONE_IP_88.2' },
