    spectrum_desc: { en: 'End-to-end solutions for the connected age.', de: 'End-to-End-Lösungen für das vernetzte Zeitalter.', et: 'Otsast lõpuni lahendused ühendatud ajastule.', fr: 'Solutions de bout en bout pour l\'ère connectée.', it: 'Soluzioni end-to-end per l\'era connessa.' },
