    bandwidth_desc: { en: 'Visualizing the flow of global information. Our network handles traffic for 3 of the top 5 streaming platforms.', de: 'Visualisierung des globalen Informationsflusses. Unser Netzwerk verwaltet den Traffic für 3 der Top 5 Streaming-Plattformen.', et: 'Globaalse informatsiooni voo visualiseerimine. Meie võrk haldab liiklust 3-le 5-st parimast voogedastusplatvormist.', fr: 'Visualisation du flux d\'informations mondiales. Notre réseau gère le trafic pour 3 des 5 meilleures plateformes de streaming.', it: 'Visualizzazione del flusso di informazioni globali. La nostra rete gestisce il traffico per 3 delle prime 5 piattaforme di streaming.' },
