    // Health Page
    hipaa_compliant: { en: 'HIPAA Compliant AI', de: 'HIPAA-konforme KI', et: 'HIPAA ühilduv AI', fr: 'IA conforme HIPAA', it: 'IA Compatibile HIPAA' },
