    clinical_applications: { en: 'Clinical Applications', de: 'Klinische Anwendungen', et: 'Kliinilised rakendused', fr: 'Applications Cliniques', it: 'Applicazioni Cliniche' },
    clinical_app_desc: { en: 'Hover over a module to activate the diagnostic scanner.', de: 'Hovern Sie über ein Modul, um den Diagnosescanner zu aktivieren.', et: 'Hõlju mooduli kohal, et aktiveerida diagnostiline skanner.', fr: 'Survolez un module pour activer le scanner de diagnostic.', it: 'Passa il mouse su un modulo per attivare lo scanner diagnostico.' },
    ai_radiology: { en: 'AI Radiology', de: 'KI-Radiologie', et: 'AI Radioloogia', fr: 'Radiologie IA', it: 'Radiologia IA' },
    ai_radiology_desc: { en: 'Computer vision models that detect anomalies in X-rays, CTs, and MRIs with superhuman precision.', de: 'Computer-Vision-Modelle, die Anomalien in Röntgenbildern, CTs und MRTs mit übermenschlicher Präzision erkennen.', et: 'Arvutinägemise mudelid, mis tuvastavad anomaaliaid röntgenpiltides, CT-des ja MRI-des üliinimliku täpsusega.', fr: 'Modèles de vision par ordinateur qui détectent les anomalies dans les rayons X, les tomodensitogrammes et les IRM avec une précision surhumaine.', it: 'Modelli di visione artificiale che rilevano anomalie in raggi X, TC e RMN con precisione sovrumana.' },
