    genomic_desc: { en: 'Processing terabytes of DNA data to identify hereditary risks and personalize treatment plans.', de: 'Verarbeitung von Terabytes an DNA-Daten zur Identifizierung erblicher Risiken und Personalisierung von Behandlungsplänen.', et: 'Terabaitide DNA andmete töötlemine pärilike riskide tuvastamiseks ja raviplaanide isikupärastamiseks.', fr: 'Traitement de téraoctets de données ADN pour identifier les risques héréditaires et personnaliser les plans de traitement.', it: 'Elaborazione di terabyte di dati DNA per identificare rischi ereditari e personalizzare i piani di trattamento.' },
    patient_flow: { en: 'Patient Flow', de: 'Patientenfluss', et: 'Patsiendi voog', fr: 'Flux de Patients', it: 'Flusso Pazienti' },
    patient_flow_desc: { en: 'Predictive algorithms that optimize bed occupancy, staff allocation, and ER triage efficiency.', de: 'Prädiktive Algorithmen zur Optimierung der Bettenbelegung, Personalplanung und Notaufnahme-Triage.', et: 'Ennustavad algoritmid, mis optimeerivad voodihõivet, personali paigutust ja EMO triaaži tõhusust.', fr: 'Algorithmes prédictifs qui optimisent l\'occupation des lits, l\'affectation du personnel et l\'efficacité du triage aux urgences.', it: 'Algoritmi predittivi che ottimizzano l\'occupazione dei letti, l\'allocazione del personale e l\'efficienza del triage al pronto soccorso.' },
    visual_intelligence: { en: 'Visual Intelligence', de: 'Visuelle Intelligenz', et: 'Visuaalne intelligentsus', fr: 'Intelligence Visuelle', it: 'Intelligenza Visiva' },
    visual_int_desc: { en: 'Our models dont just see; they understand.', de: 'Unsere Modelle sehen nicht nur; sie verstehen.', et: 'Meie mudelid ei näe ainult; nad mõistavad.', fr: 'Nos modèles ne voient pas seulement ; ils comprennent.', it: 'I nostri modelli non vedono solo; capiscono.' },
