    status_monitoring: { en: 'STATUS: MONITORING', de: 'STATUS: ÜBERWACHUNG', et: 'STAATUS: MONITOORING', fr: 'STATUT : SURVEILLANCE', it: 'STATO: MONITORAGGIO' },

