    // FAQ
    faq_questions_title: { en: 'Questions?', de: 'Fragen?', et: 'Küsimused?', fr: 'Des questions ?', it: 'Domande?' },
    faq_questions_subtitle: { en: 'Clear answers for IT and Legal teams.', de: 'Klare Antworten für IT- und Rechtsteams.', et: 'Selged vastused IT- ja õigusmeeskondadele.', fr: 'Des réponses claires pour les équipes IT et juridiques.', it: 'Risposte chiare per i team IT e legali.' },

    faq_q1: { en: 'Can we switch between deployment models?', de: 'Können wir zwischen Bereitstellungsmodellen wechseln?', et: 'Kas me saame juurutusmudelite vahel vahetada?', fr: 'Pouvons-nous basculer entre les modèles de déploiement ?', it: 'Possiamo passare tra modelli di distribuzione?' },
    faq_a1: { en: 'Yes. Adraca is designed for portability. You can start with our Managed Cloud for rapid prototyping and migrate to a Sovereign Node or On-Prem deployment as your compliance requirements evolve.', de: 'Ja. Adraca ist auf Portabilität ausgelegt. Sie können mit unserer Managed Cloud für schnelles Prototyping beginnen und zu einem Sovereign Node oder On-Prem-Deployment migrieren.', et: 'Jah. Adraca on loodud ühilduvaks. Saate alustada meie hallatud pilvega kiireks prototüüpimiseks ja migreeruda suveräänsele sõlmle või kohapealsele juurutusele.', fr: 'Oui. Adraca est conçu pour la portabilité. Vous pouvez commencer avec notre Cloud Géré pour un prototypage rapide et migrer vers un Nœud Souverain ou un déploiement sur site.', it: 'Sì. Adraca è progettato per la portabilità. Puoi iniziare con il nostro Cloud Gestito per una prototipazione rapida e migrare a un Nodo Sovrano o distribuzione On-Prem.' },

    faq_q2: { en: 'What qualifies as a "Major Entity" for the Enterprise Node?', de: 'Was qualifiziert als "Großunternehmen" für den Enterprise Node?', et: 'Mis kvalifitseerub "Suureks üksuseks" Enterprise Node jaoks?', fr: 'Qu\'est-ce qui qualifie une "Entité Majeure" pour le Nœud Entreprise ?', it: 'Cosa si qualifica come "Entità Maggiore" per il Nodo Enterprise?' },
    faq_a2: { en: 'Generally, this is for organizations with specific on-prem requirements, high-volume throughput needs, or those operating in highly regulated sectors like banking and defense where data sovereignty is non-negotiable.', de: 'Generell gilt dies für Organisationen mit spezifischen On-Prem-Anforderungen, hohem Durchsatzbedarf oder solchen, die in stark regulierten Sektoren tätig sind.', et: 'Üldiselt on see mõeldud organisatsioonidele, kellel on spetsiifilised kohapealsed nõuded, suuremahulised läbilaskevõime vajadused.', fr: 'Généralement, c\'est pour les organisations ayant des exigences spécifiques sur site, des besoins de débit élevé.', it: 'Generalmente, questo è per organizzazioni con requisiti specifici on-prem, esigenze di throughput elevato.' },

    faq_q3: { en: 'Is there a trial period available?', de: 'Gibt es eine Testphase?', et: 'Kas prooviperiood on saadaval?', fr: 'Y a-t-il une période d\'essai disponible ?', it: 'C\'è un periodo di prova disponibile?' },
    faq_a3: { en: 'We offer a 14-day Proof of Concept (PoC) environment for qualifying enterprises. Contact our sales team to schedule a technical discovery session.', de: 'Wir bieten eine 14-tägige Proof-of-Concept (PoC)-Umgebung für qualifizierte Unternehmen an.', et: 'Pakume kvalifitseeruvatele ettevõtetele 14-päevast Proof of Concept (PoC) keskkonda.', fr: 'Nous proposons un environnement Proof of Concept (PoC) de 14 jours pour les entreprises qualifiées.', it: 'Offriamo un ambiente Proof of Concept (PoC) di 14 giorni per le imprese qualificate.' },

    faq_q4: { en: 'How does OEM licensing work for partners?', de: 'Wie funktioniert die OEM-Lizenzierung für Partner?', et: 'Kuidas toimib OEM-litsentsimine partneritele?', fr: 'Comment fonctionne la licence OEM pour les partenaires ?', it: 'Come funziona la licenza OEM per i partner?' },
    faq_a4: { en: 'OEM partners get white-label rights and specialized API access to embed our sovereign AI orchestration directly into their software products.', de: 'OEM-Partner erhalten White-Label-Rechte und spezialisierten API-Zugang.', et: 'OEM partnerid saavad white-label õigused ja spetsialiseeritud API ligipääsu.', fr: 'Les partenaires OEM obtiennent des droits en marque blanche et un accès API spécialisé.', it: 'I partner OEM ottengono diritti white-label e accesso API specializzato.' },

